let currentLocale: Locale = 'ar';

export const setLocale = (locale: Locale): void => {
  if (translations[locale]) {
    currentLocale = locale;
  }
};

export const getLocale = (): Locale => currentLocale;

export const isRTL = (): boolean => currentLocale === 'ar' || currentLocale === 'ur';

export const t = (path: string): string => {
  const parts = path.split('.');
  let curr: any = translations[currentLocale] || translations['ar'];
  for (const part of parts) {
    if (curr && curr[part] !== undefined) {
      curr = curr[part];
    } else {
      // Fallback to English if key missing in current locale
      let fallback: any = translations['en'];
      for (const p of parts) {
        if (fallback && fallback[p] !== undefined) {
          fallback = fallback[p];
        } else {
          return path;
        }
      }
      return typeof fallback === 'string' ? fallback : path;
    }
  }
  return typeof curr === 'string' ? curr : path;
};
